-- Partie 3/3 : objets ordinaires, armes à feu et contrôle final du lot.
-- Contenu D&D — lot 2 : équipement et objets magiques du SRD 5.2 (règles 2024).
--
-- Ajoute 250 objets magiques (entrées du livre : les variantes par arme ou par
-- armure de l'API Open5e sont regroupées, ex. « Arme +1 », « Langue de feu ») et
-- 103 objets ordinaires absents de la base (matériel d'aventurier, munitions,
-- outils, montures, véhicules, mousquet et pistolet). Textes traduits en français
-- (poids convertis en kg, distances en mètres) ; le nom anglais est ajouté en
-- locale « en » pour faciliter les rapprochements futurs.
--
-- Source : Open5e API v2, documents srd-2024 (items, magicitems), récupérés le
-- 2026-09-30.
--
-- Licence : ce contenu inclut des éléments du System Reference Document 5.2
-- (« SRD 5.2 ») de Wizards of the Coast LLC, disponible sur
-- https://www.dndbeyond.com/srd. Le SRD 5.2 est placé sous licence Creative
-- Commons Attribution 4.0 International (https://creativecommons.org/licenses/by/4.0/legalcode).
--
-- Idempotente : un objet dont le nom FR existe déjà n'est pas réinséré.

do $$
declare
  rec record;
  v_id int;
  v_inserted int := 0;
begin
  for rec in
    select * from (values
  ($t$Acide (fiole)$t$, $t$Acid$t$, $t$equipement_general$t$, 0.5, $t${"amount":25,"currency":"gp"}$t$::jsonb, null, false, true, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Quand vous effectuez l'action Attaquer, vous pouvez remplacer l'une de vos attaques par le lancer d'une fiole d'acide sur une créature ou un objet que vous voyez à 6 m ou moins. La cible doit réussir un JS de Dextérité (DD 8 + votre modificateur de Dextérité + votre bonus de maîtrise) ou subir 2d6 dégâts d'acide.$t$),
  ($t$Feu grégeois (flasque)$t$, $t$Alchemist's Fire$t$, $t$equipement_general$t$, 0.5, $t${"amount":50,"currency":"gp"}$t$::jsonb, null, false, true, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Quand vous effectuez l'action Attaquer, vous pouvez remplacer l'une de vos attaques par le lancer d'une flasque de feu grégeois sur une créature ou un objet que vous voyez à 6 m ou moins. La cible doit réussir un JS de Dextérité (DD 8 + votre modificateur de Dextérité + votre bonus de maîtrise) ou subir 1d4 dégâts de feu et prendre feu (elle subit 1d4 dégâts de feu au début de chacun de ses tours jusqu'à ce qu'une créature éteigne les flammes par une action).$t$),
  ($t$Eau bénite (flasque)$t$, $t$Holy Water$t$, $t$equipement_general$t$, 0.5, $t${"amount":25,"currency":"gp"}$t$::jsonb, null, false, true, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Quand vous effectuez l'action Attaquer, vous pouvez remplacer l'une de vos attaques par le lancer d'une flasque d'eau bénite sur une créature que vous voyez à 6 m ou moins. La cible doit réussir un JS de Dextérité (DD 8 + votre modificateur de Dextérité + votre bonus de maîtrise) ou subir 2d8 dégâts radiants si c'est un fiélon ou un mort-vivant.$t$),
  ($t$Antitoxine (fiole)$t$, $t$Antitoxin$t$, $t$equipement_general$t$, 0, $t${"amount":50,"currency":"gp"}$t$::jsonb, null, false, true, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Par une action bonus, vous pouvez boire une fiole d'antitoxine pour avoir l'avantage aux jets de sauvegarde pour éviter ou terminer l'état empoisonné pendant 1 heure.$t$),
  ($t$Mousquet$t$, $t$Musket$t$, $t$arme$t$, 5, $t${"amount":500,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Arme de guerre à distance (arme à feu).$t$),
  ($t$Pistolet$t$, $t$Pistol$t$, $t$arme$t$, 1.5, $t${"amount":250,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Arme de guerre à distance (arme à feu).$t$),
  ($t$Flèches (20)$t$, $t$Arrows (20)$t$, $t$equipement_general$t$, 0.5, $t${"amount":1,"currency":"gp"}$t$::jsonb, null, false, true, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Munitions pour les armes à flèches, par paquet de 20. Généralement rangées dans un carquois.$t$),
  ($t$Carreaux (20)$t$, $t$Bolts (20)$t$, $t$equipement_general$t$, 0.75, $t${"amount":1,"currency":"gp"}$t$::jsonb, null, false, true, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Munitions pour les arbalètes, par paquet de 20. Généralement rangés dans un étui à carreaux.$t$),
  ($t$Balles d'arme à feu (10)$t$, $t$Bullets, Firearm (10)$t$, $t$equipement_general$t$, 1, $t${"amount":3,"currency":"gp"}$t$::jsonb, null, false, true, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Munitions pour les armes à feu, par paquet de 10. Généralement rangées dans une bourse.$t$),
  ($t$Billes de fronde (20)$t$, $t$Bullets, Sling (20)$t$, $t$equipement_general$t$, 0.75, $t${"amount":0.04,"currency":"gp"}$t$::jsonb, null, false, true, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Munitions pour la fronde, par paquet de 20. Généralement rangées dans une bourse.$t$),
  ($t$Aiguilles de sarbacane (50)$t$, $t$Needles (50)$t$, $t$equipement_general$t$, 0.5, $t${"amount":1,"currency":"gp"}$t$::jsonb, null, false, true, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Munitions pour la sarbacane, par paquet de 50. Généralement rangées dans une bourse.$t$),
  ($t$Billes (sac de 1 000)$t$, $t$Ball Bearings$t$, $t$equipement_general$t$, 1, $t${"amount":1,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Par une action Utiliser, vous pouvez répandre les billes sur une zone plane carrée de 3 m de côté à 3 m ou moins de vous. Une créature qui entre dans la zone pour la première fois lors d'un tour doit réussir un JS de Dextérité DD 10 ou tomber à terre. Il faut 10 minutes pour les ramasser.$t$),
  ($t$Tonneau$t$, $t$Barrel$t$, $t$equipement_general$t$, 35, $t${"amount":2,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Contient jusqu'à 160 litres de liquide ou 110 litres de marchandises sèches.$t$),
  ($t$Panier$t$, $t$Basket$t$, $t$equipement_general$t$, 1, $t${"amount":0.4,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Contient jusqu'à 20 kg dans un volume d'environ 55 litres.$t$),
  ($t$Clochette$t$, $t$Bell$t$, $t$equipement_general$t$, 0, $t${"amount":1,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Agitée par une action Utiliser, elle produit un son audible jusqu'à 18 m.$t$),
  ($t$Palan$t$, $t$Block and Tackle$t$, $t$equipement_general$t$, 2.5, $t${"amount":1,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Permet de hisser jusqu'à quatre fois le poids que vous pouvez normalement soulever.$t$),
  ($t$Livre$t$, $t$Book$t$, $t$equipement_general$t$, 2.5, $t${"amount":25,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Ouvrage de fiction ou documentaire. Consulter un livre documentaire exact sur un sujet donne un bonus de +5 aux tests d'Intelligence (Arcanes, Histoire, Nature ou Religion) portant sur ce sujet.$t$),
  ($t$Bouteille en verre$t$, $t$Bottle, Glass$t$, $t$equipement_general$t$, 1, $t${"amount":2,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Contient jusqu'à 75 cl.$t$),
  ($t$Seau$t$, $t$Bucket$t$, $t$equipement_general$t$, 1, $t${"amount":0.05,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Contient jusqu'à 15 litres.$t$),
  ($t$Chausse-trappes (sac de 20)$t$, $t$Caltrops$t$, $t$equipement_general$t$, 1, $t${"amount":1,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Par une action Utiliser, vous pouvez répandre les chausse-trappes sur un carré de 1,50 m de côté à 1,50 m ou moins de vous. Une créature qui entre dans la zone pour la première fois lors d'un tour doit réussir un JS de Dextérité DD 15 ou subir 1 dégât perforant, et sa vitesse tombe à 0 jusqu'au début de son prochain tour. Il faut 10 minutes pour les ramasser.$t$),
  ($t$Étui à carreaux$t$, $t$Case, Crossbow Bolt$t$, $t$equipement_general$t$, 0.5, $t${"amount":1,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Contient jusqu'à 20 carreaux.$t$),
  ($t$Étui à cartes ou parchemins$t$, $t$Case, Map or Scroll$t$, $t$equipement_general$t$, 0.5, $t${"amount":1,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Contient jusqu'à 10 feuilles de papier ou 5 feuilles de parchemin.$t$),
  ($t$Chaîne (3 m)$t$, $t$Chain$t$, $t$equipement_general$t$, 5, $t${"amount":5,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Par une action Utiliser, vous pouvez entourer de la chaîne une créature non consentante à 1,50 m ou moins, empoignée, neutralisée ou entravée, en réussissant un test de Force (Athlétisme) DD 13. Elle est alors entravée jusqu'à s'échapper (test de Force (Athlétisme) ou de Dextérité (Acrobaties) DD 18). La chaîne peut être brisée (Force DD 20).$t$),
  ($t$Coffre$t$, $t$Chest$t$, $t$equipement_general$t$, 12.5, $t${"amount":5,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Contient jusqu'à 340 litres.$t$),
  ($t$Fourrage (1 jour)$t$, $t$Feed (per day)$t$, $t$equipement_general$t$, 5, $t${"amount":0.05,"currency":"gp"}$t$::jsonb, null, false, true, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Ration quotidienne de nourriture pour une monture.$t$),
  ($t$Flasque$t$, $t$Flask$t$, $t$equipement_general$t$, 0.5, $t${"amount":0.02,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Contient jusqu'à 50 cl.$t$),
  ($t$Piège à mâchoires$t$, $t$Hunting Trap$t$, $t$equipement_general$t$, 12.5, $t${"amount":5,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Par une action Utiliser, vous pouvez tendre ce cercle d'acier denté, fixé par une lourde chaîne à un objet immobile. Une créature qui marche sur la plaque de pression doit réussir un JS de Dextérité DD 13 ou subir 1d4 dégâts perforants et voir sa vitesse tomber à 0 jusqu'à ce qu'elle se libère (test de Force (Athlétisme) DD 13, chaque échec infligeant 1 dégât perforant).$t$),
  ($t$Cruche$t$, $t$Jug$t$, $t$equipement_general$t$, 2, $t${"amount":0.02,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Contient jusqu'à 4 litres.$t$),
  ($t$Échelle (3 m)$t$, $t$Ladder$t$, $t$equipement_general$t$, 12.5, $t${"amount":0.1,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Échelle de 3 m ; il faut escalader pour monter ou descendre.$t$),
  ($t$Lampe$t$, $t$Lamp$t$, $t$equipement_general$t$, 0.5, $t${"amount":0.5,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Brûle de l'huile et diffuse une lumière vive dans un rayon de 4,50 m et une lumière faible sur 9 m de plus.$t$),
  ($t$Loupe$t$, $t$Magnifying Glass$t$, $t$equipement_general$t$, 0, $t${"amount":100,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Donne l'avantage aux tests pour évaluer ou examiner un objet très détaillé. Permet aussi d'allumer un feu avec une lumière aussi vive que celle du soleil, de l'amadou et environ 5 minutes.$t$),
  ($t$Menottes$t$, $t$Manacles$t$, $t$equipement_general$t$, 3, $t${"amount":2,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Par une action Utiliser, vous pouvez menotter une créature non consentante de taille P ou M à 1,50 m ou moins, empoignée, neutralisée ou entravée, en réussissant un test de Dextérité (Escamotage) DD 13. Elle est alors entravée jusqu'à s'échapper (test de Dextérité (Escamotage) DD 20). Les menottes se brisent avec un test de Force (Athlétisme) DD 25.$t$),
  ($t$Carte$t$, $t$Map$t$, $t$equipement_general$t$, 0, $t${"amount":1,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Consulter une carte exacte donne un bonus de +5 aux tests de Sagesse (Survie) pour s'orienter dans le lieu représenté.$t$),
  ($t$Parfum (fiole)$t$, $t$Perfume$t$, $t$equipement_general$t$, 0, $t${"amount":5,"currency":"gp"}$t$::jsonb, null, false, true, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Pendant 1 heure après s'être parfumé, on a l'avantage aux tests de Charisme (Persuasion) pour influencer un humanoïde indifférent à 1,50 m ou moins.$t$),
  ($t$Poison ordinaire (fiole)$t$, $t$Poison, Basic$t$, $t$equipement_general$t$, 0, $t${"amount":100,"currency":"gp"}$t$::jsonb, null, false, true, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Par une action bonus, vous pouvez enduire une arme ou jusqu'à trois munitions. Une créature qui subit des dégâts perforants ou tranchants de l'arme ou de la munition empoisonnée subit 1d4 dégâts de poison supplémentaires. Le poison reste 1 minute ou jusqu'à ce qu'il soit délivré.$t$),
  ($t$Perche (3 m)$t$, $t$Pole$t$, $t$equipement_general$t$, 3.5, $t${"amount":0.05,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Permet de toucher quelque chose jusqu'à 3 m. Donne l'avantage au test de Force (Athlétisme) d'un saut en hauteur ou en longueur, en l'utilisant comme perche.$t$),
  ($t$Carquois$t$, $t$Quiver$t$, $t$equipement_general$t$, 0.5, $t${"amount":1,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Contient jusqu'à 20 flèches.$t$),
  ($t$Bélier portatif$t$, $t$Ram, Portable$t$, $t$equipement_general$t$, 17.5, $t${"amount":4,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Permet d'enfoncer des portes avec un bonus de +4 au test de Force. Une autre créature peut vous aider à le manier, ce qui vous donne l'avantage au test.$t$),
  ($t$Robe$t$, $t$Robe$t$, $t$equipement_general$t$, 2, $t${"amount":1,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Vêtement à valeur professionnelle ou cérémonielle ; certains lieux et événements n'admettent que les personnes portant une robe aux couleurs ou symboles requis.$t$),
  ($t$Selle exotique$t$, $t$Saddle (Exotic)$t$, $t$equipement_general$t$, 20, $t${"amount":60,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Selle conçue pour les montures inhabituelles, aquatiques ou volantes.$t$),
