  ($t$Selle d'équitation$t$, $t$Saddle (Riding)$t$, $t$equipement_general$t$, 12.5, $t${"amount":10,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Selle ordinaire pour les montures.$t$),
  ($t$Pelle$t$, $t$Shovel$t$, $t$equipement_general$t$, 2.5, $t${"amount":2,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$En 1 heure de travail, permet de creuser un trou de 1,50 m de côté dans de la terre ou une matière similaire.$t$),
  ($t$Longue-vue$t$, $t$Spyglass$t$, $t$equipement_general$t$, 0.5, $t${"amount":1000,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Les objets observés à travers la longue-vue paraissent deux fois plus grands.$t$),
  ($t$Ficelle (3 m)$t$, $t$String$t$, $t$equipement_general$t$, 0, $t${"amount":0.1,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Ficelle de 3 m ; on peut y faire un nœud par une action Utiliser.$t$),
  ($t$Fiole$t$, $t$Vial$t$, $t$equipement_general$t$, 0, $t${"amount":1,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Contient jusqu'à 12 cl.$t$),
  ($t$Kit d'escalade$t$, $t$Climber's Kit$t$, $t$outil$t$, 6, $t${"amount":25,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Crampons, gants, pitons et harnais. Par une action Utiliser, vous vous ancrez : vous ne pouvez pas chuter de plus de 7,50 m depuis le point d'ancrage, ni vous en éloigner de plus de 7,50 m sans vous désancrer (action bonus).$t$),
  ($t$Outils d'alchimiste$t$, $t$Alchemist's Supplies (50 GP)$t$, $t$outil$t$, 4, $t${"amount":50,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Caractéristique : Intelligence. Utiliser : identifier une substance (DD 15) ou allumer un feu (DD 15). Fabriquer : acide, feu grégeois, sacoche à composants, huile, papier, parfum.$t$),
  ($t$Outils de brasseur$t$, $t$Brewer's Supplies (20 GP)$t$, $t$outil$t$, 4.5, $t${"amount":20,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Caractéristique : Intelligence. Utiliser : détecter une boisson empoisonnée (DD 15) ou identifier un alcool (DD 10). Fabriquer : antitoxine.$t$),
  ($t$Outils de calligraphe$t$, $t$Calligrapher's Supplies (10 GP)$t$, $t$outil$t$, 2.5, $t${"amount":10,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Caractéristique : Dextérité. Utiliser : rédiger un texte orné difficile à contrefaire (DD 15). Fabriquer : encre, parchemin de sort.$t$),
  ($t$Outils de charpentier$t$, $t$Carpenter's Tools (8 GP)$t$, $t$outil$t$, 3, $t${"amount":8,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Caractéristique : Force. Utiliser : condamner ou forcer une porte ou un contenant (DD 20). Fabriquer : gourdin, massue, bâton de combat, tonneau, coffre, échelle, perche, bélier portatif, torche.$t$),
  ($t$Outils de cartographe$t$, $t$Cartographer's Tools (15 GP)$t$, $t$outil$t$, 3, $t${"amount":15,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Caractéristique : Sagesse. Utiliser : dresser la carte d'une petite zone (DD 15). Fabriquer : carte.$t$),
  ($t$Outils de cordonnier$t$, $t$Cobbler's Tools (5 GP)$t$, $t$outil$t$, 2.5, $t${"amount":5,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Caractéristique : Dextérité. Utiliser : modifier des chaussures pour donner l'avantage au prochain test de Dextérité (Acrobaties) de leur porteur (DD 10). Fabriquer : kit d'escalade.$t$),
  ($t$Ustensiles de cuisinier$t$, $t$Cook's Utensils (1 GP)$t$, $t$outil$t$, 4, $t${"amount":1,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Caractéristique : Sagesse. Utiliser : améliorer le goût d'un plat (DD 10) ou détecter une nourriture avariée ou empoisonnée (DD 15). Fabriquer : rations.$t$),
  ($t$Kit de déguisement$t$, $t$Disguise Kit$t$, $t$outil$t$, 1.5, $t${"amount":25,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Caractéristique : Charisme. Utiliser : se maquiller (DD 10). Fabriquer : costume.$t$),
