  ($t$Navire de guerre$t$, $t$Warship$t$, $t$monture_vehicule$t$, 0, $t${"amount":25000,"currency":"gp"}$t$::jsonb, null, false, false, $t$Manuel des Joueurs (2024) / SRD 5.2$t$, $t$Navire lourdement armé conçu pour le combat naval (vitesse 4 km/h, équipage 60, 60 passagers).$t$)
    ) as t(name_fr, name_en, category, weight, cost, rarity, attunement, consumable, source, description)
  loop
    if not exists (
      select 1 from public.translations tr
       where tr.entity_type = 'item' and tr.field_name = 'name' and tr.locale = 'fr'
         and lower(tr.value) = lower(rec.name_fr)
    ) then
      insert into public.items (category, weight, cost, source, rarity, requires_attunement, consumable)
        values (rec.category, rec.weight, rec.cost, rec.source, rec.rarity, rec.attunement, rec.consumable)
        returning id into v_id;
      insert into public.translations (entity_type, entity_id, field_name, locale, value) values
        ('item', v_id::text, 'name', 'fr', rec.name_fr),
        ('item', v_id::text, 'name', 'en', rec.name_en),
        ('item', v_id::text, 'description', 'fr', rec.description);
      v_inserted := v_inserted + 1;
    end if;
  end loop;
  raise notice 'objets insérés : %', v_inserted;
end $$;

-- Propriétés des nouvelles armes (armes à feu).
insert into public.weapon_properties (item_id, damage_dice, damage_type, properties, range)
select i.id, w.damage_dice, w.damage_type, w.properties, w.range
  from (values
  ($t$Mousquet$t$, $t$1d12$t$, $t$perforant$t$, $t$["munitions","chargement","deux mains"]$t$::jsonb, $t${"normal":12,"max":36}$t$::jsonb),
  ($t$Pistolet$t$, $t$1d10$t$, $t$perforant$t$, $t$["munitions","chargement"]$t$::jsonb, $t${"normal":9,"max":27}$t$::jsonb)
  ) as w(name_fr, damage_dice, damage_type, properties, range)
  join public.translations tr
    on tr.entity_type = 'item' and tr.field_name = 'name' and tr.locale = 'fr' and tr.value = w.name_fr
  join public.items i on i.id::text = tr.entity_id
 where not exists (select 1 from public.weapon_properties wp where wp.item_id = i.id);

-- Contrôle final : la migration s'exécute en une transaction ; toute anomalie annule tout.
